#include <list>
#include <iostream>

int main() {
    std::list<int> l1 = {1, 2, 3};
    std::list<int> l2 = {10, 20, 30};

    // Move the element '20' from l2 to the front of l1
    auto it_20 = ++l2.begin(); // Iterator to 20

    // O(1) operation
    l1.splice(l1.begin(), l2, it_20);

    // l1 is now {20, 1, 2, 3}
    // l2 is now {10, 30}

    // The iterator 'it_20' is still valid, pointing to 20 in l1
}
